-- Constellation hosted data model. Run this migration in a Supabase project.
-- All application access goes through the RPCs at the bottom of this file;
-- tables are deliberately not readable or writable from the browser.
create extension if not exists pgcrypto;

create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  username text not null unique check (username ~ '^[a-z0-9_.-]{3,32}$'),
  name text not null check (char_length(name) between 1 and 40),
  bio text not null default '', avatar text not null default '✨',
  status text not null default 'online' check (status in ('online','idle','dnd','invisible')),
  created_at timestamptz not null default now()
);
create table if not exists public.servers (
  id uuid primary key default gen_random_uuid(), name text not null check (char_length(name) between 1 and 80),
  description text not null default 'Your community, your constellation.', owner uuid not null references public.profiles(id),
  icon text not null default '🌌', rules text not null default '', boost integer not null default 0 check (boost between 0 and 3), created_at timestamptz not null default now()
);
create table if not exists public.members (server_id uuid references public.servers(id) on delete cascade, user_id uuid references public.profiles(id) on delete cascade, primary key(server_id,user_id));
create table if not exists public.roles (id uuid primary key default gen_random_uuid(), server_id uuid not null references public.servers(id) on delete cascade, name text not null, color text not null default '#aeb3c5', color2 text not null default '', emoji text not null default '', permissions jsonb not null default '[]', position integer not null);
create table if not exists public.member_roles (server_id uuid not null, user_id uuid not null, role_id uuid references public.roles(id) on delete cascade, primary key(server_id,user_id,role_id), foreign key(server_id,user_id) references public.members(server_id,user_id) on delete cascade);
create table if not exists public.channels (id uuid primary key default gen_random_uuid(), server_id uuid not null references public.servers(id) on delete cascade, name text not null, topic text not null default '', category text not null default 'TEXT CHANNELS', allowed jsonb not null default '[]', readonly boolean not null default false);
create table if not exists public.messages (id uuid primary key default gen_random_uuid(), channel_id uuid references public.channels(id) on delete cascade, sender uuid not null references public.profiles(id), recipient uuid references public.profiles(id), body text not null check(char_length(body) between 1 and 4000), created_at timestamptz not null default now(), edited boolean not null default false, pinned boolean not null default false, check ((channel_id is null) <> (recipient is null)));
create table if not exists public.reactions (message_id uuid references public.messages(id) on delete cascade, user_id uuid references public.profiles(id) on delete cascade, emoji text not null, primary key(message_id,user_id,emoji));
create table if not exists public.invites (code text primary key, server_id uuid not null references public.servers(id) on delete cascade, created_at timestamptz not null default now());
create table if not exists public.bans (server_id uuid references public.servers(id) on delete cascade, user_id uuid references public.profiles(id) on delete cascade, primary key(server_id,user_id));
create table if not exists public.audit (id bigint generated always as identity primary key, server_id uuid references public.servers(id) on delete cascade, actor uuid references public.profiles(id), action text not null, created_at timestamptz not null default now());

alter table public.profiles enable row level security; alter table public.servers enable row level security; alter table public.members enable row level security; alter table public.roles enable row level security; alter table public.member_roles enable row level security; alter table public.channels enable row level security; alter table public.messages enable row level security; alter table public.reactions enable row level security; alter table public.invites enable row level security; alter table public.bans enable row level security; alter table public.audit enable row level security;
revoke all on all tables in schema public from anon, authenticated;

create or replace function public.new_profile() returns trigger language plpgsql security definer set search_path=public as $$
declare v_name text := coalesce(nullif(trim(new.raw_user_meta_data->>'name'),''), split_part(new.email,'@',1)); v_username text := lower(coalesce(nullif(trim(new.raw_user_meta_data->>'username'),''), split_part(new.email,'@',1)));
begin
  if v_username !~ '^[a-z0-9_.-]{3,32}$' then raise exception 'Choose a username with 3–32 letters, numbers, dots, dashes or underscores'; end if;
  insert into public.profiles(id,username,name) values(new.id,v_username,left(v_name,40)); return new;
end $$;
create trigger auth_user_profile after insert on auth.users for each row execute procedure public.new_profile();

create or replace function public.app_permissions(p_server uuid,p_user uuid default auth.uid()) returns jsonb language sql stable security definer set search_path=public as $$
  select case when s.owner=p_user then '["view_channels","send_messages","manage_messages","manage_channels","manage_roles","manage_server","kick_members","ban_members","create_invites","administrator"]'::jsonb else coalesce(jsonb_agg(distinct permission), '[]'::jsonb) end
  from servers s left join roles r on r.server_id=s.id and (r.position=0 or exists(select 1 from member_roles mr where mr.role_id=r.id and mr.server_id=s.id and mr.user_id=p_user)) left join lateral jsonb_array_elements_text(r.permissions) permission on true where s.id=p_server group by s.owner
$$;
create or replace function public.app_member(p_server uuid,p_user uuid default auth.uid()) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from members where server_id=p_server and user_id=p_user) $$;
create or replace function public.app_has(p_server uuid,p_permission text,p_user uuid default auth.uid()) returns boolean language sql stable security definer set search_path=public as $$ select app_member(p_server,p_user) and (app_permissions(p_server,p_user) ? 'administrator' or app_permissions(p_server,p_user) ? p_permission) $$;
create or replace function public.app_public_profile(p_user uuid) returns jsonb language sql stable security definer set search_path=public as $$ select jsonb_build_object('id',id,'username',username,'name',name,'bio',bio,'avatar',avatar,'status',status) from profiles where id=p_user $$;

create or replace function public.app_state() returns jsonb language plpgsql security definer set search_path=public as $$
declare v_me uuid:=auth.uid();
begin
 if v_me is null then raise exception 'Please sign in'; end if;
 return jsonb_build_object('user',app_public_profile(v_me),'permissions','["view_channels","send_messages","manage_messages","manage_channels","manage_roles","manage_server","kick_members","ban_members","create_invites","administrator"]'::jsonb,
 'servers',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'description',s.description,'owner',s.owner,'icon',s.icon,'rules',s.rules,'boost',s.boost,'permissions',app_permissions(s.id,v_me),
 'roles',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'server_id',r.server_id,'name',r.name,'color',r.color,'color2',r.color2,'emoji',r.emoji,'permissions',r.permissions,'position',r.position) order by r.position desc) from roles r where r.server_id=s.id),'[]'::jsonb),
 'members',coalesce((select jsonb_agg(app_public_profile(m.user_id)||jsonb_build_object('roles',coalesce((select jsonb_agg(role_id) from member_roles where server_id=s.id and user_id=m.user_id),'[]'::jsonb))) from members m where m.server_id=s.id),'[]'::jsonb),
 'channels',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'server_id',c.server_id,'name',c.name,'topic',c.topic,'category',c.category,'allowed',c.allowed,'readonly',c.readonly) order by c.category,c.name) from channels c where c.server_id=s.id and (jsonb_array_length(c.allowed)=0 or app_permissions(s.id,v_me) ? 'administrator' or exists(select 1 from member_roles mr where mr.server_id=s.id and mr.user_id=v_me and c.allowed ? mr.role_id::text))),'[]'::jsonb),
 'bans',case when app_has(s.id,'ban_members',v_me) then coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'name',p.name,'username',p.username)) from bans b join profiles p on p.id=b.user_id where b.server_id=s.id),'[]'::jsonb) else '[]'::jsonb end,
 'audit',case when app_has(s.id,'manage_server',v_me) then coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'server_id',a.server_id,'actor',a.actor,'action',a.action,'created',extract(epoch from a.created_at)) order by a.id desc) from (select * from audit where server_id=s.id order by id desc limit 50) a),'[]'::jsonb) else '[]'::jsonb end)) from servers s join members membership on membership.server_id=s.id and membership.user_id=v_me),'[]'::jsonb),
 'contacts',coalesce((select jsonb_agg(app_public_profile(x.id)) from (select distinct case when sender=v_me then recipient else sender end id from messages where channel_id is null and (sender=v_me or recipient=v_me)) x),'[]'::jsonb));
end $$;

create or replace function public.app_messages(p_channel uuid default null,p_user uuid default null) returns jsonb language plpgsql security definer set search_path=public as $$
declare v_me uuid:=auth.uid(); v_server uuid;
begin
 if p_channel is not null then select server_id into v_server from channels where id=p_channel; if v_server is null or not app_member(v_server,v_me) then raise exception 'Cannot view this channel'; end if;
 elsif p_user is null or p_user=v_me then raise exception 'Recipient not found'; end if;
 return coalesce((select jsonb_agg(jsonb_build_object('id',m.id,'channel_id',m.channel_id,'sender',m.sender,'recipient',m.recipient,'body',m.body,'created',extract(epoch from m.created_at),'edited',m.edited,'pinned',m.pinned,'reactions',coalesce((select jsonb_agg(jsonb_build_object('emoji',r.emoji,'count',r.count)) from (select emoji,count(*) from reactions where message_id=m.id group by emoji) r),'[]'::jsonb)) order by m.created_at) from (select * from messages where (p_channel is not null and channel_id=p_channel) or (p_channel is null and channel_id is null and ((sender=v_me and recipient=p_user) or (sender=p_user and recipient=v_me))) order by created_at desc limit 300) m),'[]'::jsonb);
end $$;

create or replace function public.app_api(p_action text,p_payload jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path=public as $$
declare v_me uuid:=auth.uid(); v_server uuid:=nullif(p_payload->>'server','')::uuid; v_id uuid:=nullif(p_payload->>'id','')::uuid; v_user uuid:=nullif(p_payload->>'user','')::uuid; v_channel uuid:=nullif(p_payload->>'channel','')::uuid; v_role uuid:=nullif(p_payload->>'role','')::uuid; v_action text; v_code text; v_message messages%rowtype; v_target profiles%rowtype; v_pos integer;
begin
 if v_me is null then raise exception 'Please sign in'; end if;
 if p_action='profile' then update profiles set name=left(trim(p_payload->>'name'),40),avatar=left(trim(p_payload->>'avatar'),8),bio=left(coalesce(p_payload->>'bio',''),500),status=coalesce(p_payload->>'status','online') where id=v_me; return '{}'::jsonb; end if;
 if p_action='server/create' then insert into servers(name,owner,icon) values(left(trim(p_payload->>'name'),80),v_me,left(coalesce(p_payload->>'icon','🌌'),8)) returning id into v_server; insert into members values(v_server,v_me); insert into roles(server_id,name,color,permissions,position) values(v_server,'@everyone','#aeb3c5','["view_channels","send_messages","create_invites"]',0); insert into channels(server_id,name,topic,category,readonly) values(v_server,'general','Welcome to general','TEXT CHANNELS',false),(v_server,'introductions','Welcome to introductions','TEXT CHANNELS',false),(v_server,'announcements','Welcome to announcements','INFORMATION',true); insert into audit(server_id,actor,action) values(v_server,v_me,'Created server'); return jsonb_build_object('id',v_server); end if;
 if p_action='server/join' then select server_id into v_server from invites where code=trim(p_payload->>'code'); if v_server is null then raise exception 'Invite not found'; end if; if exists(select 1 from bans where server_id=v_server and user_id=v_me) then raise exception 'You are banned from this server'; end if; insert into members values(v_server,v_me) on conflict do nothing; insert into audit(server_id,actor,action) values(v_server,v_me,'Joined server'); return jsonb_build_object('id',v_server); end if;
 if p_action='dm/open' then select * into v_target from profiles where username=lower(trim(p_payload->>'username')); if not found or v_target.id=v_me then raise exception 'User not found'; end if; return jsonb_build_object('user',app_public_profile(v_target.id)); end if;
 if p_action='message/send' then if v_channel is not null then select server_id into v_server from channels where id=v_channel; if not app_has(v_server,'send_messages',v_me) then raise exception 'You cannot send in this channel'; end if; if exists(select 1 from channels where id=v_channel and readonly) and not app_has(v_server,'manage_messages',v_me) then raise exception 'You cannot send in this channel'; end if; insert into messages(channel_id,sender,body) values(v_channel,v_me,left(trim(p_payload->>'body'),4000)) returning id into v_id; else if v_user is null or v_user=v_me or not exists(select 1 from profiles where id=v_user) then raise exception 'Recipient not found'; end if; insert into messages(sender,recipient,body) values(v_me,v_user,left(trim(p_payload->>'body'),4000)) returning id into v_id; end if; return jsonb_build_object('id',v_id); end if;
 if p_action like 'message/%' then select * into v_message from messages where id=v_id; if not found then raise exception 'Message not found'; end if; if v_message.channel_id is not null then select server_id into v_server from channels where id=v_message.channel_id; if not app_member(v_server,v_me) then raise exception 'Private message'; end if; elsif v_me not in (v_message.sender,v_message.recipient) then raise exception 'Private message'; end if; v_action=split_part(p_action,'/',2); if v_action='react' then if exists(select 1 from reactions where message_id=v_id and user_id=v_me and emoji=p_payload->>'emoji') then delete from reactions where message_id=v_id and user_id=v_me and emoji=p_payload->>'emoji'; else insert into reactions values(v_id,v_me,p_payload->>'emoji'); end if; elsif v_action='edit' and v_message.sender=v_me then update messages set body=left(trim(p_payload->>'body'),4000),edited=true where id=v_id; elsif v_action='delete' and (v_message.sender=v_me or (v_server is not null and app_has(v_server,'manage_messages',v_me))) then delete from messages where id=v_id; elsif v_action='pin' and v_server is not null and app_has(v_server,'manage_messages',v_me) then update messages set pinned=not pinned where id=v_id; else raise exception 'Not permitted'; end if; return '{}'::jsonb; end if;
 if p_action like 'server/%' then if not app_member(v_server,v_me) then raise exception 'You are not a member of this server'; end if; v_action=split_part(p_action,'/',2); if v_action='invite' then if not app_has(v_server,'create_invites',v_me) then raise exception 'Missing permission: create_invites'; end if; v_code=encode(gen_random_bytes(8),'hex'); insert into invites(code,server_id) values(v_code,v_server); return jsonb_build_object('code',v_code); elsif v_action='update' and app_has(v_server,'manage_server',v_me) then update servers set name=left(trim(p_payload->>'name'),80),icon=left(p_payload->>'icon',8),description=left(coalesce(p_payload->>'description',''),500),rules=left(coalesce(p_payload->>'rules',''),5000),boost=least(3,greatest(0,coalesce((p_payload->>'boost')::integer,0))) where id=v_server; elsif v_action='leave' and not exists(select 1 from servers where id=v_server and owner=v_me) then delete from members where server_id=v_server and user_id=v_me; elsif v_action='transfer' and exists(select 1 from servers where id=v_server and owner=v_me) then update servers set owner=v_user where id=v_server and exists(select 1 from members where server_id=v_server and user_id=v_user); elsif v_action='delete' and exists(select 1 from servers where id=v_server and owner=v_me) then delete from servers where id=v_server; else raise exception 'Not permitted'; end if; return '{}'::jsonb; end if;
 if p_action='role/save' then if not app_has(v_server,'manage_roles',v_me) then raise exception 'Missing permission: manage_roles'; end if; if v_id is null then if not exists(select 1 from servers where id=v_server and owner=v_me) then raise exception 'Only the owner can create roles'; end if; select coalesce(max(position),0)+1 into v_pos from roles where server_id=v_server; insert into roles(server_id,name,color,color2,emoji,permissions,position) values(v_server,left(trim(p_payload->>'name'),40),coalesce(p_payload->>'color','#5865f2'),coalesce(p_payload->>'color2',''),left(coalesce(p_payload->>'emoji',''),8),coalesce(p_payload->'permissions','[]'),v_pos); else update roles set name=case when position=0 then '@everyone' else left(trim(p_payload->>'name'),40) end,color=coalesce(p_payload->>'color','#5865f2'),color2=coalesce(p_payload->>'color2',''),emoji=left(coalesce(p_payload->>'emoji',''),8),permissions=coalesce(p_payload->'permissions','[]') where id=v_id and server_id=v_server; end if; return '{}'::jsonb; end if;
 if p_action='role/delete' then if not app_has(v_server,'manage_roles',v_me) then raise exception 'Missing permission: manage_roles'; end if; delete from roles where id=v_id and server_id=v_server and position>0; return '{}'::jsonb; end if;
 if p_action='role/move' then if not app_has(v_server,'manage_roles',v_me) then raise exception 'Missing permission: manage_roles'; end if; select position into v_pos from roles where id=v_id and server_id=v_server; if p_payload->>'direction'='up' then update roles set position=position+1 where server_id=v_server and position=(select min(position) from roles where server_id=v_server and position>v_pos); update roles set position=v_pos+1 where id=v_id; else update roles set position=position-1 where server_id=v_server and position=(select max(position) from roles where server_id=v_server and position<v_pos and position>0); update roles set position=v_pos-1 where id=v_id; end if; return '{}'::jsonb; end if;
 if p_action='member/moderate' then if v_user=v_me or exists(select 1 from servers where id=v_server and owner=v_user) then raise exception 'Cannot moderate this member'; end if; if p_payload->>'action'='unban' and app_has(v_server,'ban_members',v_me) then delete from bans where server_id=v_server and user_id=v_user; elsif p_payload->>'action'='kick' and app_has(v_server,'kick_members',v_me) then delete from members where server_id=v_server and user_id=v_user; elsif p_payload->>'action'='ban' and app_has(v_server,'ban_members',v_me) then insert into bans values(v_server,v_user) on conflict do nothing; delete from members where server_id=v_server and user_id=v_user; else raise exception 'Not permitted'; end if; return '{}'::jsonb; end if;
 if p_action in ('channel/save','channel/delete') then if not app_has(v_server,'manage_channels',v_me) then raise exception 'Missing permission: manage_channels'; end if; if p_action='channel/delete' then delete from channels where id=v_id and server_id=v_server; else if v_id is null then insert into channels(server_id,name,topic,category,allowed,readonly) values(v_server,left(trim(p_payload->>'name'),60),left(coalesce(p_payload->>'topic',''),300),left(coalesce(p_payload->>'category','TEXT CHANNELS'),50),coalesce(p_payload->'allowed','[]'),coalesce((p_payload->>'readonly')::boolean,false)); else update channels set name=left(trim(p_payload->>'name'),60),topic=left(coalesce(p_payload->>'topic',''),300),category=left(coalesce(p_payload->>'category','TEXT CHANNELS'),50),allowed=coalesce(p_payload->'allowed','[]'),readonly=coalesce((p_payload->>'readonly')::boolean,false) where id=v_id and server_id=v_server; end if; end if; return '{}'::jsonb; end if;
 if p_action='member/role' then if not app_has(v_server,'manage_roles',v_me) then raise exception 'Missing permission: manage_roles'; end if; if coalesce((p_payload->>'enabled')::boolean,false) then insert into member_roles values(v_server,v_user,v_role) on conflict do nothing; else delete from member_roles where server_id=v_server and user_id=v_user and role_id=v_role; end if; return '{}'::jsonb; end if;
 raise exception 'Unknown operation';
end $$;

revoke all on function public.app_state(), public.app_messages(uuid,uuid), public.app_api(text,jsonb) from public;
grant execute on function public.app_state(), public.app_messages(uuid,uuid), public.app_api(text,jsonb) to authenticated;
